'use client';

import {useState,useEffect,useRef,type FormEvent} from 'react';
import {Sparkles,ArrowUp,ArrowUpRight,Check,LoaderCircle,MapPin,Clock3,ShieldCheck,Home,Brush,CalendarDays,RotateCcw,PanelLeft,Plus,MessageSquare,Bell,UserRound,LogOut,ChevronDown,Search,ArrowRight,Building2,Settings2,Info,X} from 'lucide-react';
import './chat.css';
import {AuthScreen,RoleDashboard,AutomationForm,roleInfo} from './role-workspace';
import {Modal,PropertyCard,PropertyWizard} from './workspace-ui';

type Row=Record<string,any>;
type Role='guest'|'owner'|'cleaner';
type Message={id:string;sender:'user'|'assistant';text:string;block?:string;payload?:Row;done?:boolean};
type Question={key:string;text:string;label:string;min?:number;max?:number};
type Flow={kind:'profile'|'property';role:Role;after:string;answers:Row;questions:Question[];index:number};
const empty={properties:[],ownProperties:[],bookings:[],jobs:[],applications:[],notifications:[],messages:[],profile:null,user:null};
const money=(n:number)=>new Intl.NumberFormat('ru-RU').format(n)+' ₸';
const date=(n:number)=>new Date(n*1000).toLocaleString('ru-RU',{timeZone:'Asia/Almaty',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const localDate=(hours:number)=>new Date(Date.now()+(hours+5)*3600000).toISOString().slice(0,16);
const labels:Row={requested:'Ожидает подтверждения',confirmed:'Подтверждена',cancelled:'Отменено',expired:'Срок истёк',open:'Можно откликнуться',assigned:'Исполнитель назначен',in_progress:'В работе',submitted:'На проверке',completed:'Работа принята',pending:'Отклик отправлен',accepted:'Вы назначены',rejected:'Выбран другой исполнитель',withdrawn:'Вы отказались от задания'};
const propertyQuestions:Question[]=[
  {key:'title',text:'Как назовём квартиру? Например: «Светлая студия у набережной».',label:'Название'},
  {key:'city',text:'В каком городе находится квартира?',label:'Город'},
  {key:'district',text:'В каком районе? Это поможет гостям найти подходящий вариант.',label:'Район'},
  {key:'address',text:'Напишите точный адрес: улицу, дом и квартиру. Его получат только подтверждённый гость и назначенный исполнитель.',label:'Адрес'},
  {key:'price',text:'Сколько стоит проживание за сутки? Напишите сумму в тенге.',label:'Цена за сутки',min:100,max:10000000},
  {key:'rooms',text:'Сколько в квартире комнат?',label:'Комнаты',min:1,max:20},
  {key:'capacity',text:'Сколько гостей можно разместить?',label:'Гости',min:1,max:50},
  {key:'cleaningMinutes',text:'Сколько минут нужно на уборку между гостями? Обычно 60–90 минут.',label:'Уборка, минут',min:30,max:1440},
  {key:'description',text:'Расскажите об удобствах и правилах: что есть в квартире, когда можно заехать, что важно знать гостю.',label:'Описание и правила'},
];

export default function Chat(){
  const [data,setData]=useState<Row>(empty),[messages,setMessages]=useState<Message[]>([]),[input,setInput]=useState('');
  const [role,setRole]=useState<Role>('guest'),[flow,setFlow]=useState<Flow|null>(null),[busy,setBusy]=useState(false),[ready,setReady]=useState(false);
  const transcript=useRef<HTMLDivElement>(null),composer=useRef<HTMLTextAreaElement>(null),messageCounter=useRef(0),lock=useRef(false),pendingProperty=useRef<Row|null>(null);
  const user=data.user,profile=data.profile,myId=user?.id;
  const [panel,setPanel]=useState<string|null>('dashboard'),[sidebar,setSidebar]=useState(false),[selectedProperty,setSelectedProperty]=useState<Row|null>(null),[panelError,setPanelError]=useState(''),[pollError,setPollError]=useState(false),[notificationToast,setNotificationToast]=useState<Row|null>(null);
  const [compact,setCompact]=useState(false);
  const drawer=useRef<HTMLElement>(null);
  useEffect(()=>{const query=window.matchMedia('(max-width:760px)');const update=()=>setCompact(query.matches);update();query.addEventListener('change',update);return()=>query.removeEventListener('change',update);},[]);
  useEffect(()=>{if(compact&&sidebar)drawer.current?.querySelector<HTMLButtonElement>('button')?.focus();},[sidebar,compact]);
  const loadedIdentity=useRef<string|null>(null),loadGeneration=useRef(0);
  const seenNotifications=useRef<{userId:string;ids:Set<string>}|null>(null);
  const unread=data.notifications.filter((n:Row)=>!n.read).length;
  const displayName=profile?.name||user?.name||'Ваш аккаунт';
  function openPanel(name:string){setSidebar(false);setPanelError('');setPanel(name);}
  function navigate(intent:string){setSidebar(false);setPanel(null);runIntent(intent,data,role);}
  useEffect(()=>{if(!user)return;const refresh=()=>{if(document.visibilityState==='visible')load().then(()=>setPollError(false)).catch(()=>setPollError(true));};const timer=setInterval(refresh,30000);document.addEventListener('visibilitychange',refresh);return()=>{clearInterval(timer);document.removeEventListener('visibilitychange',refresh);};},[user?.id]);
  async function publishProperty(property:Row,owner:Row){await post('profile',owner);const result=await post(panel==='edit-property'?'properties/'+selectedProperty?.id:'properties',panel==='edit-property'?{...property,action:'update'}:property);await load().catch(()=>setPollError(true));setPanel('properties');say(result.message||'Квартира опубликована.','choices',{items:[['Мои квартиры','Мои квартиры'],['Заявки гостей','Заявки гостей']]});}
  async function openNotification(n:Row){
    const parts=String(n.dedupe||'').split(':'),kind=parts[0],entityId=['arrival','departure','expired'].includes(kind)?parts[2]:parts[1];
    let desired:Role=role;
    if(['application','submitted','overdue','started','declined','owner-confirmed','booking'].includes(kind))desired='owner';
    if(['approved','assigned','late','job-cancelled','not-selected','job-open','revision'].includes(kind))desired='cleaner';
    if(['confirmed','paid'].includes(kind))desired='guest';
    if(['arrival','departure','expired'].includes(kind)&&['owner','guest'].includes(parts[1]))desired=parts[1] as Role;
    try{
      let state=data;
      if(desired!==role){if(!JSON.parse(profile?.roles||'[]').includes(desired)){openPanel('roles');return;}await post('settings',{activeRole:desired});state=await load();setRole(desired);setMessages([]);setFlow(null);}
      setPanel(null);
      if(['application','submitted','overdue','started','declined'].includes(kind)){listJobs(state,'owner');return;}
      if(['approved','assigned','late','job-cancelled','not-selected','job-open','revision'].includes(kind)){listJobs(state,'cleaner',kind!=='job-open');return;}
      const booking=state.bookings.find((b:Row)=>b.id===entityId);
      if(booking){listBookings({...state,bookings:[booking]},booking.owner_id===myId?'owner':'guest');return;}
      if(/уборк/i.test(n.body))listJobs(state,desired==='owner'?'owner':'cleaner',desired!=='owner');else listBookings(state,desired==='owner'?'owner':'guest');
    }catch(e:any){setPanelError(e.message);setPanel('notifications');}
  }
  async function switchRole(next:Role){setPanelError('');try{await post('settings',{activeRole:next});await load();setRole(next);setFlow(null);setMessages([]);setPanel('dashboard');}catch(e:any){setPanelError(e.message);}}
  async function signout(){await post('auth/logout');loadGeneration.current++;setData(empty);setInput('');setMessages([]);setFlow(null);setPanel('dashboard');loadedIdentity.current=null;seenNotifications.current=null;setNotificationToast(null);}
  async function markRead(){setPanelError('');try{await post('notifications');await load();}catch(e:any){setPanelError(e.message);}}

  const say=(text:string,block?:string,payload?:Row)=>{const id='message-'+Date.now()+'-'+(++messageCounter.current);setMessages(v=>[...v,{id,sender:'assistant',text,block,payload}]);return id;};
  const finish=(id:string)=>setMessages(v=>v.map(m=>m.id===id?{...m,done:true}:m));
  async function load(){
    const generation=++loadGeneration.current;
    const response=await fetch('/api/state',{cache:'no-store'});const body=await response.json() as Row;
    if(generation!==loadGeneration.current)return empty;
    if(response.status===401){setData(empty);setNotificationToast(null);seenNotifications.current=null;loadedIdentity.current=null;return empty;}
    if(!response.ok)throw new Error(body.error||'Не удалось получить данные.');
    const previous=seenNotifications.current;
    if(previous && previous.userId===body.user?.id){const fresh=body.notifications.find((n:Row)=>!previous.ids.has(n.id)&&!n.read);if(fresh)setNotificationToast(fresh);}
    seenNotifications.current={userId:body.user?.id,ids:new Set(body.notifications.map((n:Row)=>n.id))};
    if(loadedIdentity.current!==body.user.id){setRole(body.settings?.active_role||'guest');setMessages([]);setInput('');setFlow(null);setSelectedProperty(null);setPanel('dashboard');loadedIdentity.current=body.user.id;}
    setData(body);return body;
  }
  useEffect(()=>{load().catch(()=>say('Сейчас нет связи с сервером. Можно попробовать подключиться ещё раз.','retry')).finally(()=>setReady(true));},[]);
  useEffect(()=>{const el=transcript.current;if(el)el.scrollTop=el.scrollHeight;},[messages.length,flow,busy]);
  useEffect(()=>{if(composer.current){composer.current.style.height='auto';composer.current.style.height=Math.min(composer.current.scrollHeight,140)+'px';}},[input]);
  async function post(path:string,body:Row={}){
    const response=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
    const result=await response.json() as Row;if(!response.ok)throw new Error(result.error||'Изменение не подтверждено.');return result;
  }
  async function perform(path:string,body:Row,messageId?:string,after?:(state:Row,result:Row)=>void){
    if(lock.current)return;lock.current=true;setBusy(true);
    try{const result=await post(path,body);if(messageId)finish(messageId);const state=await load();say(result.message||'Готово.');after?.(state,result);}
    catch(e:any){say(e.message+' Действие не подтверждено. Можно повторить его.');}
    finally{lock.current=false;setBusy(false);composer.current?.focus();}
  }
  function signin(intent:string){sessionStorage.setItem('ai-arenda-next-intent',intent);say('Чтобы сохранять ваши квартиры, брони и задания, сначала нужно войти. После входа продолжим здесь.','signin',{intent});}
  function beginProfile(target:Role,after:string,state=data,edit=false){
    if(!state.user){signin(after);return false;}
    const p=state.profile||{};
    if(!edit&&p.roles&&JSON.parse(p.roles).includes(target))return true;
    const answers:Row={...p,roles:[...new Set([...(p.roles?JSON.parse(p.roles):[]),target])]};
    const questions:Question[]=[{key:'name',text:'Как к вам обращаться?',label:'Имя'},{key:'contact',text:'Как с вами связаться? Напишите телефон или имя пользователя в мессенджере. Контакт не публикуется в общем каталоге.',label:'Контакт'},{key:'city',text:'В каком городе вы планируете пользоваться сервисом?',label:'Город'}];
    if(target==='cleaner')questions.push({key:'districts',text:'В каких районах вам удобно брать уборки?',label:'Районы'},{key:'experience',text:'Расскажите немного об опыте: какие уборки вы выполняете и что умеете?',label:'Опыт'},{key:'availability',text:'В какие дни и часы вы готовы работать?',label:'График'});
    const needed=questions.filter(q=>edit||!String(answers[q.key]||'').trim());
    setRole(target);
    if(!needed.length){say('Проверьте сведения. Подключу нужную возможность после вашего подтверждения.','profile-review',{answers,target,after});return false;}
    say(target==='cleaner'?'Познакомимся и подготовим вашу анкету. Я задам несколько коротких вопросов.':'Познакомимся. Я задам несколько коротких вопросов, а затем продолжим вашу задачу.');
    setFlow({kind:'profile',role:target,after,answers,questions:needed,index:0});say(needed[0].text);return false;
  }
  function startProperty(state=data){
    if(!beginProfile('owner','property',state))return;
    setRole('owner');const answers:Row={};if(state.profile?.city)answers.city=state.profile.city;
    const questions=propertyQuestions.filter(q=>!answers[q.key]);
    say('Добавим квартиру прямо здесь. Сначала соберём сведения, затем я покажу их вам перед публикацией.');
    setFlow({kind:'property',role:'owner',after:'property',answers,questions,index:0});say(questions[0].text);
  }
  function listProperties(state=data,own=false,query=''){
    const budgetMatch=query.match(/(?:до|бюджет)\s*(\d[\d\s]*)(?:тыс|000|₸|тенге)?/i);
    let budget=budgetMatch?Number(budgetMatch[1].replace(/\s/g,'')):null;
    if(budget&&budget<1000&&/тыс/i.test(query))budget*=1000;
    const people=/на двоих|для двоих/i.test(query)?2:Number(query.match(/(\d+)\s*(?:гост|человек)/i)?.[1]||0);
    const city=state.properties.find((p:Row)=>query.toLowerCase().includes(p.city.toLowerCase()))?.city;
    const requestedUnit=/почас|на час|часов/i.test(query)?'hour':/посуточ|на сут/i.test(query)?'day':null;
    const requestedType=/хостел/i.test(query)?'hostel':/гостиниц|отел|номер/i.test(query)?'hotel':/\bдом\b/i.test(query)?'house':null;
    const properties=(own?state.ownProperties:state.properties).filter((p:Row)=>(!budget||p.price<=budget)&&(!people||p.capacity>=people)&&(!city||p.city===city)&&(!requestedUnit||p.rate_unit===requestedUnit)&&(!requestedType||p.property_type===requestedType));
    say(properties.length?(own?'Вот ваши квартиры. Можно посмотреть заявки или создать уборку.':'Вот предложения'+(city?' в городе '+city:'')+'. Выберите подходящее — я уточню время и проверю возможность бронирования.'):(own?'У вас пока нет добавленных квартир. Можем подключить первую.':'Подходящих квартир пока нет. Можно изменить запрос или посмотреть учебный пример.'),'properties',{items:properties,own,budget,people});
  }
  function listBookings(state=data,actor=role){
    const items=state.bookings.filter((b:Row)=>actor==='owner'?b.owner_id===state.user?.id:b.guest_id===state.user?.id);
    say(items.length?'Вот ваши бронирования. Все даты указаны по времени Павлодара.':'У вас пока нет бронирований. Когда появится заявка, её можно будет проверить прямо в разговоре.','bookings',{items,actor});
  }
  function listJobs(state=data,actor=role,mine=false){
    const items=state.jobs.filter((j:Row)=>actor==='owner'?j.owner_id===state.user?.id:mine?j.assigned_to===state.user?.id||state.applications.some((a:Row)=>a.job_id===j.id&&a.user_id===state.user?.id):j.status==='open'&&j.end>Date.now()/1000);
    say(items.length?(actor==='owner'?'Вот уборки по вашим квартирам. Здесь можно посмотреть отклики и принять работу.':mine?'Вот ваши отклики и назначения.':'Вот доступные уборки. В карточках — время, район и условия. Адрес появится после назначения.'):(actor==='owner'?'Пока нет заданий. Можем опубликовать уборку по вашей квартире.':mine?'У вас пока нет откликов и назначений.':'Сейчас подходящих открытых уборок нет. Можно подготовить анкету и вернуться к поиску позже.'),'jobs',{items,actor,applications:state.applications});
  }
  function runIntent(intent:string,state=data,target=role){
    const needed:Row={property:'owner','own-properties':'owner','owner-jobs':'owner',job:'owner',properties:'guest',jobs:'cleaner','my-jobs':'cleaner','cleaner-profile':'cleaner'};
    if(needed[intent]&&needed[intent]!==role){say('Эта задача доступна в кабинете «'+roleInfo[needed[intent] as Role].name+'». Подключите или выберите его в аккаунте.');openPanel('roles');return;}

    if(intent==='property'){setPanel(null);setFlow(null);if(!state.user){signin('property');return;}openPanel('add-property');return;}
    if(intent==='cleaner-profile'){if(beginProfile('cleaner','jobs',state))say('Ваша анкета уже сохранена. Могу показать доступные уборки.','choices',{items:[['Показать уборки','Найти уборку'],['Изменить анкету','Изменить анкету']]});return;}
    if(intent==='properties'){setRole('guest');if(!state.user){signin('properties');return;}listProperties(state);return;}
    if(intent==='own-properties'){setRole('owner');if(!beginProfile('owner','own-properties',state))return;listProperties(state,true);return;}
    if(intent==='jobs'){setRole('cleaner');if(!state.user){signin('jobs');return;}listJobs(state,'cleaner');return;}
    if(intent==='my-jobs'){setRole('cleaner');if(!state.user){signin('my-jobs');return;}listJobs(state,'cleaner',true);return;}
    if(intent==='owner-jobs'){setRole('owner');if(!beginProfile('owner','owner-jobs',state))return;listJobs(state,'owner');return;}
    if(intent==='bookings'){if(!state.user){signin('bookings');return;}listBookings(state,target);return;}
    if(intent==='job'){setRole('owner');if(!beginProfile('owner','job',state))return;if(!state.ownProperties.length){say('Для задания нужна квартира. Давайте сначала добавим её.','choices',{items:[['Добавить квартиру','Хочу сдать квартиру']]});return;}say('Уточним время и условия уборки. Эти сведения увидят исполнители.','job-form',{properties:state.ownProperties});return;}
    if(intent==='profile'){if(!state.user){signin('profile');return;}beginProfile(target,'profile-done',state,true);return;}
    if(intent==='book-property'&&pendingProperty.current){chooseProperty(pendingProperty.current,state);return;}
    if(intent==='notifications'){openPanel('notifications');return;}
    if(intent==='profile-done'){post('settings',{activeRole:target}).then(()=>load()).then(()=>{setRole(target);setPanel('dashboard');}).catch(e=>say(e.message));return;}
  }
  useEffect(()=>{if(!ready||!data.user)return;const pending=sessionStorage.getItem('ai-arenda-next-intent');if(pending){sessionStorage.removeItem('ai-arenda-next-intent');runIntent(pending,data);}},[ready,data.user?.id]);
  async function send(value=input){
    const text=value.trim();if(!text||lock.current||!ready)return;setInput('');setMessages(v=>[...v,{id:'user-'+Date.now()+'-'+(++messageCounter.current),sender:'user',text}]);
    if(/^(стоп|отмена|отменить ввод|начать сначала)$/i.test(text)){setFlow(null);say('Хорошо, остановимся. Что хотите сделать дальше?');return;}
    if(flow){
      const q=flow.questions[flow.index];let answer:any=text;
      if(q.min!==undefined){answer=Number(text.replace(/\s/g,'').replace(/(?:₸|тенге|минут[аы]?|комнат[аы]?|гост[ьяей]+)\.?$/i,''));if(!Number.isInteger(answer)||answer<q.min||answer>(q.max||Infinity)){say(`Напишите целое число от ${q.min} до ${q.max}.`);return;}}
      else if(text.length>(q.key==='description'?2500:q.key==='experience'?1000:q.key==='name'?100:q.key==='city'?80:q.key==='contact'?120:300)){say('Ответ получился слишком длинным. Напишите, пожалуйста, короче.');return;}
      const answers={...flow.answers,[q.key]:answer}, next=flow.index+1;
      if(next<flow.questions.length){setFlow({...flow,answers,index:next});say(flow.questions[next].text);}
      else{setFlow(null);say(flow.kind==='property'?'Всё собрали. Проверьте сведения перед публикацией.':'Проверьте, правильно ли я вас понял.',flow.kind==='property'?'property-review':'profile-review',{answers,target:flow.role,after:flow.after});}
      return;
    }
    if(/сда(?:ть|вать|ю)|добав.*(?:кварт|объект|номер|дом)|подключ.*кварт/i.test(text)){runIntent('property');return;}
    if(/изменить анкет|изменить профил/i.test(text)){runIntent('profile',data,/анкет/i.test(text)?'cleaner':role);return;}
    if(/хочу работ|ищу работ|работать на убор|стать.*исполн|заполн.*анкет/i.test(text)){runIntent('cleaner-profile');return;}
    if(/нужна убор|создать.*убор|заказать.*убор|найти.*(?:уборщ|исполнител)/i.test(text)){runIntent('job');return;}
    if(/мои квартир|мои объект|моя недвижимость|мо[иё] жиль/i.test(text)){runIntent('own-properties');return;}
    if(/мои (?:отклик|задан|уборк)|назначени/i.test(text)){runIntent('my-jobs');return;}
    if(/уборк.*моих|мои.*исполнител/i.test(text)){runIntent('owner-jobs');return;}
    if(/найти убор|показать убор|доступн.*убор|свободн.*убор/i.test(text)){runIntent('jobs');return;}
    if(/мои брон|заявки гост|заезд|показать брони/i.test(text)){runIntent('bookings');return;}
    if(/уведомлен|что нового/i.test(text)){if(!user){signin('notifications');return;}try{await load();openPanel('notifications');}catch(e:any){say(e.message);}return;}
    if(/демо|учебн|пример/i.test(text)){say('Могу добавить две учебные квартиры и уборку. Они будут видны только вам; реальное заселение и выплаты по ним невозможны.','demo');return;}
    if(/что.*уме|как.*работ|о сервисе|помощь/i.test(text)){say('Я помогаю снять жильё, подключить квартиры и найти работу по уборке. Всё делаем в этом разговоре: я уточняю сведения, а вы подтверждаете важные действия.\n\nСейчас доступны базовые сценарии. Свободная языковая модель, мессенджеры и автоматические платежи ещё не подключены.','choices',{items:[['Снять квартиру','Хочу снять квартиру'],['Сдать квартиру','Хочу сдать квартиру'],['Работать на уборке','Хочу работать на уборке']]});return;}
    if(/(?:квартир|жиль|снять|аренд|посут|хостел|гостиниц|номер|почас)/i.test(text)){setRole('guest');if(!user){signin('properties');return;}listProperties(data,false,text);return;}
    lock.current=true;setBusy(true);try{const answer=await post('chat',{text,role});say(answer.text);await load();}catch(e:any){say(e.message);}finally{lock.current=false;setBusy(false);composer.current?.focus();}
  }
  function chooseProperty(p:Row,state=data){pendingProperty.current=p;if(!beginProfile('guest','book-property',state))return;pendingProperty.current=null;setRole('guest');say('Уточним время проживания в «'+p.title+'».','booking-form',{property:p,requestKey:crypto.randomUUID()});}
  async function formSubmit(event:FormEvent<HTMLFormElement>,m:Message,path:string,extra:Row={}){
    event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget).entries()) as Row;
    if(values.start)values.start+='+05:00';if(values.end)values.end+='+05:00';
    await perform(path,{...values,...extra},m.id);
  }
  const button=(label:string,fn:()=>void,secondary=false)=><button disabled={busy} className={secondary?'inline-button secondary':'inline-button'} onClick={fn}>{label}{!secondary&&<ArrowUpRight size={14}/>}</button>;
  function renderBlock(m:Message){
    const p=m.payload||{};
    if(m.done)return <div className="done"><Check size={14}/>Сохранено</div>;
    if(m.block==='signin')return <a className="inline-button" href="/signin-with-chatgpt?return_to=/" target="_top">Войти и продолжить<ArrowUpRight size={14}/></a>;
    if(m.block==='retry')return button('Подключиться снова',async()=>{try{await load();finish(m.id);say('Связь восстановлена. Продолжим.');}catch{say('Пока не удалось подключиться. Попробуйте чуть позже.');}});
    if(m.block==='choices')return <div className="inline-actions">{p.items.map(([label,text]:string[])=><button key={label} disabled={busy} onClick={()=>send(text)}>{label}<ArrowUpRight size={13}/></button>)}</div>;
    if(m.block==='demo')return button('Добавить учебный пример',()=>{if(!user){signin('properties');return;}perform('demo',{},m.id,(state)=>listProperties(state));});
    if(m.block==='profile-review')return <div className="inline-card"><dl>{['name','contact','city',...(p.target==='cleaner'?['districts','experience','availability']:[])].map(key=><div key={key}><dt>{({name:'Имя',contact:'Контакт',city:'Город',districts:'Районы',experience:'Опыт',availability:'График'} as Row)[key]}</dt><dd>{p.answers[key]}</dd></div>)}</dl>{p.target==='cleaner'&&<small>Это анкета для откликов. Назначение на уборку подтверждает заказчик.</small>}<div className="inline-actions">{button('Всё верно, сохранить',()=>perform('profile',p.answers,m.id,state=>runIntent(p.after,state,p.target)))}{button('Заполнить заново',()=>{finish(m.id);beginProfile(p.target,p.after,{...data,profile:null});},true)}</div></div>;
    if(m.block==='property-review')return <div className="inline-card"><h3><Home size={17}/>{p.answers.title}</h3><dl>{propertyQuestions.filter(q=>q.key!=='title').map(q=><div key={q.key}><dt>{q.label}</dt><dd>{q.key==='price'?money(p.answers[q.key]):p.answers[q.key]}</dd></div>)}</dl><small><ShieldCheck size={13}/>Точный адрес скрыт от общего каталога.</small><div className="inline-actions">{button('Опубликовать квартиру',()=>perform('properties',p.answers,m.id))}{button('Заполнить заново',()=>{finish(m.id);startProperty();},true)}</div></div>;
    if(m.block==='properties')return <div className="inline-list">{p.items.map((item:Row)=><PropertyCard key={item.id} item={item} own={p.own} onDetails={()=>{setSelectedProperty(item);openPanel('property-detail');}} onAction={()=>p.own?(setSelectedProperty(item),openPanel('property-detail')):chooseProperty(item)}/>)}{!p.items.length&&<div className="empty-state"><Home size={28}/><h3>{p.own?'Добавьте свою первую квартиру':'Пока нет подходящих квартир'}</h3><p>{p.own?'Укажите расположение, стоимость и правила — перед публикацией сможете всё проверить.':'Попробуйте другой запрос или изучите учебные объекты.'}</p>{button(p.own?'Добавить квартиру':'Показать пример',()=>p.own?runIntent('property'):send('Покажи учебный пример'))}</div>}{p.own&&p.items.length>0&&<div className="inline-actions">{button('Добавить квартиру',()=>runIntent('property'))}{button('Заявки гостей',()=>runIntent('bookings',data,'owner'),true)}{button('Уборки по квартирам',()=>runIntent('owner-jobs'),true)}</div>}</div>;
    if(m.block==='booking-form')return <form className="inline-card inline-form" onSubmit={e=>formSubmit(e,m,'bookings',{propertyId:p.property.id,requestKey:p.requestKey})}><h3>{p.property.title}</h3><div className="input-row"><label>Заезд<input required name="start" type="datetime-local" defaultValue={localDate(24)}/></label><label>Выезд<input required name="end" type="datetime-local" defaultValue={localDate(p.property.rate_unit==='hour'?26:48)}/></label></div><label>Гостей<input name="guests" type="number" min={1} max={p.property.capacity} defaultValue={1} required/></label><small>Время Павлодара, UTC+5. {money(p.property.price)} за каждый начатый {p.property.rate_unit==='hour'?'час':'период 24 часа'}. Итог рассчитывается сервером. Заявку подтверждает владелец.</small><button className="inline-button" disabled={busy}>Отправить заявку<ArrowUpRight size={14}/></button></form>;
    if(m.block==='job-form')return <form className="inline-card inline-form" onSubmit={e=>formSubmit(e,m,'jobs')}><label>Какая квартира?<select name="propertyId" required>{p.properties.map((x:Row)=><option key={x.id} value={x.id}>{x.title}</option>)}</select></label><div className="input-row"><label>Начало<input name="start" type="datetime-local" required defaultValue={localDate(24)}/></label><label>Окончание<input name="end" type="datetime-local" required defaultValue={localDate(26)}/></label></div><label>Вознаграждение, ₸<input name="fee" type="number" min={100} max={1000000} defaultValue={4000} required/></label><label>Что нужно сделать?<textarea name="description" required maxLength={2000} placeholder="Состав работ, средства, бельё и другие условия"/></label><small>Время Павлодара, UTC+5. Исполнители увидят район и условия, точный адрес — после назначения.</small><button className="inline-button" disabled={busy}>Опубликовать задание<ArrowUpRight size={14}/></button></form>;
    if(m.block==='confirm-booking')return <form className="inline-card inline-form" onSubmit={e=>formSubmit(e,m,'bookings/'+p.id,{action:'confirm'})}><label>Стоимость уборки после выезда, ₸<input name="cleaningFee" type="number" min={0} max={1000000} defaultValue={4000}/></label><small>При сумме больше нуля задание на уборку создастся автоматически. Подтверждение брони не подтверждает поступление оплаты.</small><button className="inline-button" disabled={busy}>Подтвердить бронь<Check size={14}/></button></form>;
    if(m.block==='bookings')return <div className="inline-list"><div className="booking-tabs">{role==='owner'&&<button className={p.actor==='owner'?'selected':''} onClick={()=>listBookings(data,'owner')}>Заявки гостей</button>}{role==='guest'&&<button className={p.actor==='guest'?'selected':''} onClick={()=>listBookings(data,'guest')}>Мои поездки</button>}</div>{p.items.map((b:Row)=><div key={b.id} className="inline-card"><div className="card-meta"><CalendarDays size={13}/>{b.status==='completed'?'Проживание завершено':labels[b.status]}{b.demo_owner&&<span className="tag">Учебная</span>}</div><h3>{b.title}</h3><p>{date(b.start)} → {date(b.end)}</p><small>{b.guests} гостей · {money(b.amount)} · {b.payment_status==='owner_verified'?'Оплата отмечена владельцем':'Оплата не подтверждена'}</small>{b.address&&<p className="private"><ShieldCheck size={13}/>{b.address}{b.owner_contact?' · '+b.owner_contact:''}</p>}<div className="inline-actions">{p.actor==='owner'&&b.status==='requested'&&button('Подтвердить',()=>say('Подтвердим заявку на «'+b.title+'»?','confirm-booking',b))}{p.actor==='owner'&&b.status==='confirmed'&&b.payment_status!=='owner_verified'&&button('Отметить оплату',()=>say('Вы проверили фактическое поступление '+money(b.amount)+'? Эта отметка не выполняет банковскую операцию.','payment',{id:b.id}),true)}{['requested','confirmed'].includes(b.status)&&button('Отменить',()=>say('Отменить бронь «'+b.title+'»? Возврат оплаты, если потребуется, согласуется отдельно.','cancel',{id:b.id}),true)}{button('Сообщить о проблеме',()=>say('Опишите ситуацию. Обращение будет сохранено у другого участника брони.','issue',{id:b.id,kind:'booking'}),true)}</div></div>)}{!p.items.length&&button('Подобрать квартиру',()=>runIntent('properties'))}</div>;
    if(m.block==='decline-job')return button('Подтвердить отказ',()=>perform('jobs/'+p.id,{action:'decline'},m.id));
    if(m.block==='payment')return button('Да, поступление проверено',()=>perform('bookings/'+p.id,{action:'paid'},m.id));
    if(m.block==='cancel')return button('Подтвердить отмену',()=>perform('bookings/'+p.id,{action:'cancel'},m.id));
    if(m.block==='jobs')return <div className="inline-list">{p.items.map((j:Row)=>{const owner=p.actor==='owner',assigned=j.assigned_to===myId,apps=(p.applications||[]).filter((a:Row)=>a.job_id===j.id),applied=apps.find((a:Row)=>a.user_id===myId);return <div className="inline-card" key={j.id}><div className="card-meta"><Brush size={13}/>{labels[j.status]}{j.demo_owner&&<span className="tag">Учебное</span>}</div><h3>{j.title}</h3><p>{j.city}, {j.district} · {date(j.start)} — {date(j.end)}</p><p>{j.description}</p><strong>{money(j.fee)}<small> за выполнение</small></strong>{j.address&&<p className="private"><ShieldCheck size={13}/>{j.address}{j.owner_contact?' · '+j.owner_contact:''}</p>}{j.report&&<p className="report">Отчёт: {j.report}</p>}{owner&&j.status==='open'&&apps.map((a:Row)=><div className="applicant" key={a.id}><b>{a.name}</b><small>{a.experience} · {a.availability}</small>{button('Назначить исполнителя',()=>perform('jobs/'+j.id,{action:'assign',applicationId:a.id},m.id))}</div>)}<div className="inline-actions">{!owner&&j.status==='open'&&(!applied||['withdrawn','rejected'].includes(applied.status))&&button(applied?'Откликнуться снова':'Откликнуться',()=>{if(beginProfile('cleaner','jobs'))perform('jobs/'+j.id,{action:'apply'},m.id);})}{applied&&!assigned&&<small>{labels[applied.status]}</small>}{assigned&&j.status==='assigned'&&button('Отказаться от назначения',()=>say('Отказаться от уборки до начала работы? Владелец получит уведомление, задание снова станет доступным.','decline-job',{id:j.id}),true)}{assigned&&j.status==='assigned'&&button('Начать уборку',()=>perform('jobs/'+j.id,{action:'start'},m.id))}{assigned&&j.status==='in_progress'&&button('Отправить отчёт',()=>say('Проверьте результат и опишите выполненную работу.','report',{id:j.id}))}{owner&&j.status==='submitted'&&button('Вернуть на доработку',()=>say('Что нужно исправить? Замечания получит назначенный исполнитель.','issue',{id:j.id,kind:'job',action:'revise'}),true)}{owner&&j.status==='submitted'&&button('Принять работу',()=>perform('jobs/'+j.id,{action:'approve'},m.id))}{(owner||assigned)&&button('Есть проблема',()=>say('Что произошло? Сохраню обращение для другого участника задания.','issue',{id:j.id,kind:'job'}),true)}</div></div>;})}<div className="inline-actions">{p.actor==='owner'?button('Создать уборку',()=>runIntent('job'),true):<>{button('Мои отклики и работа',()=>runIntent('my-jobs'),true)}{button('Заполнить анкету',()=>runIntent('cleaner-profile'),true)}</>}</div></div>;
    if(m.block==='report')return <form className="inline-card inline-form" onSubmit={e=>formSubmit(e,m,'jobs/'+p.id,{action:'submit',checklist:[true,true,true,true]})}>{['Кухня и санузел убраны','Бельё заменено','Мусор вынесен, поверхности чистые','Вода и электроприборы проверены'].map(text=><label key={text} className="check-label"><input type="checkbox" required/>{text}</label>)}<label>Отчёт<textarea name="report" required maxLength={1500} placeholder="Что сделано? Есть ли замечания?"/></label><small>Приёмку выполняет заказчик. Загрузка фотографий и выплаты пока не подключены.</small><button className="inline-button" disabled={busy}>Отправить на проверку<ArrowUpRight size={14}/></button></form>;
    if(m.block==='issue')return <form className="inline-card inline-form" onSubmit={e=>formSubmit(e,m,(p.kind==='job'?'jobs/':'bookings/')+p.id,{action:p.action||'issue'})}><label>Что произошло?<textarea name="issue" required maxLength={1500} placeholder="Опишите ситуацию"/></label><small>Для срочной помощи свяжитесь с ответственным по контакту в подтверждённой брони или назначенном задании.</small><button className="inline-button" disabled={busy}>Передать обращение<ArrowUpRight size={14}/></button></form>;
    if(m.block==='notifications')return <div className="inline-list">{p.items.map((n:Row)=><div className="inline-card" key={n.id}><p>{n.body}</p><small>{date(n.created_at)}</small></div>)}</div>;
    return null;
  }
  if(!ready)return <div className="startup-screen"><LoaderCircle className="spin" size={26}/><p>Подключаю ваше пространство…</p></div>;
  if(!user||!profile)return <AuthScreen onAuthenticated={async()=>{await load();setPanel('dashboard');setMessages([]);}}/>;
  return <div className="workspace">
    {sidebar&&<button className="sidebar-scrim" onClick={()=>setSidebar(false)} aria-label="Закрыть навигацию"/>}
    <aside ref={drawer} inert={compact&&!sidebar} onKeyDown={e=>{if(!compact||!sidebar)return;if(e.key==='Escape'){setSidebar(false);return;}if(e.key==='Tab'){const focusable=drawer.current?.querySelectorAll<HTMLElement>('button:not([disabled]),a[href]');if(!focusable?.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}} className={'workspace-sidebar '+(sidebar?'is-open':'')} aria-label="Навигация"><div className="sidebar-brand"><span className="brand-mark"><Home size={22}/></span><span>AI Аренда<small>{roleInfo[role].name}</small></span><button className="icon-button sidebar-close" onClick={()=>setSidebar(false)} aria-label="Скрыть навигацию"><X size={18}/></button></div>
    <button className="new-chat" disabled={busy||!!flow} onClick={()=>{setMessages([]);setInput('');setSidebar(false);setPanel(null);}}><Plus size={18}/>Новый разговор<MessageSquare size={16}/></button>
    <div className="nav-label">ВАШЕ ПРОСТРАНСТВО</div><nav><button className={panel==='dashboard'?'active':''} onClick={()=>{setPanel('dashboard');setSidebar(false);}}><Home size={18}/>Мой кабинет</button><button className={panel===null?'active':''} onClick={()=>{setPanel(null);setSidebar(false);}}><MessageSquare size={18}/>Ассистент<span className="nav-dot"/></button>{role==='guest'&&<button onClick={()=>navigate('properties')}><Search size={18}/>Каталог жилья</button>}{role==='owner'&&<button onClick={()=>openPanel('properties')}><Building2 size={18}/>Мои объекты<span className="nav-count">{data.ownProperties.length}</span></button>}{role!=='cleaner'&&<button onClick={()=>navigate('bookings')}><CalendarDays size={18}/>Бронирования</button>}{role==='owner'&&<button onClick={()=>navigate('owner-jobs')}><Brush size={18}/>Уборки по объектам</button>}{role==='cleaner'&&<><button onClick={()=>navigate('jobs')}><Search size={18}/>Доступные уборки</button><button onClick={()=>navigate('my-jobs')}><Check size={18}/>Мои задания</button></>}{role==='owner'&&<button onClick={()=>openPanel('automation')}><Settings2 size={18}/>Правила ассистента</button>}<button onClick={()=>openPanel('notifications')}><Bell size={18}/>Уведомления{unread>0&&<span className="nav-count unread">{unread}</span>}</button></nav>
    {role==='owner'&&<button className="sidebar-add" disabled={!ready||busy} onClick={()=>runIntent('property')}><Plus size={17}/>Добавить объект</button>}
    <div className="sidebar-guide"><span className="eyebrow">НАЧНИТЕ ЗДЕСЬ</span><h3>Ваша квартира —<br/>под вашим контролем</h3><p>Добавьте объект. Проверяйте заявки и назначайте уборки в одном месте.</p><button onClick={()=>openPanel('guide')}>Как это работает<ArrowUpRight size={14}/></button></div>
    <div className="sidebar-bottom"><button className="help-link" onClick={()=>openPanel('about')}><Info size={17}/>О сервисе и возможностях</button><button className="account-trigger" onClick={()=>openPanel('account')}><span className="avatar">{user?displayName[0]?.toUpperCase():<UserRound size={20}/>}</span><span><b>{user?displayName:'Войти в аккаунт'}</b><small>{user?roleInfo[role].name:'Сохраняйте квартиры и брони'}</small></span><ChevronDown size={16}/></button></div></aside>
    <div className="chat-app" inert={compact&&sidebar}><header className="chat-header"><div className="header-title"><button className="icon-button" onClick={()=>setSidebar(!sidebar)} aria-label="Открыть навигацию" aria-expanded={sidebar}><PanelLeft size={21}/></button><span>{panel==='dashboard'?'Мой кабинет':'Ассистент'}</span><span className="pilot-label">Пилотная версия</span></div><div className="header-actions"><button className="role-switch" onClick={()=>openPanel('roles')}>{roleInfo[role].name}<ChevronDown size={13}/></button>{role==='owner'&&<button className="header-add" disabled={!ready||busy} onClick={()=>runIntent('property')}><Plus size={16}/>Добавить объект</button>}<button className="icon-button notification-trigger" onClick={()=>openPanel('notifications')} aria-label={'Уведомления'+(unread?', непрочитанных: '+unread:'') }><Bell size={20}/>{unread>0&&<i>{unread}</i>}</button></div></header>
    {pollError&&<div className="connection-banner" role="status">Не удалось обновить данные. Проверьте соединение.<button onClick={()=>load().then(()=>setPollError(false)).catch(()=>setPollError(true))}>Повторить</button></div>}
    {panel==='dashboard'?<RoleDashboard data={data} role={role} onAction={navigate} onOpen={openPanel}/>:<main className="chat-main"><div className={'chat-transcript '+(!messages.length?'is-empty':'')} ref={transcript}>
    {!messages.length?<div className="chat-welcome"><div className="welcome-kicker"><span/>ВАШ АССИСТЕНТ ПО АРЕНДЕ</div><h1>Меньше забот.<br/><span>Больше пространства.</span></h1><p>Сдавайте квартиру, находите жильё и организуйте уборку.<br/>Начните с действия или просто напишите.</p><div className="welcome-actions">{(role==='owner'?[['property','Добавить объект','Тип, тариф и правила'],['bookings','Заявки гостей','Подтвердить бронирование'],['owner-jobs','Уборки','Назначения и приёмка']]:role==='guest'?[['properties','Найти жильё','Выбрать объект и даты'],['bookings','Мои брони','Контакты и статус'],['profile','Мой профиль','Имя и контакт']]:[['jobs','Найти уборку','Работа в вашем городе'],['my-jobs','Мои задания','Начать и сдать работу'],['profile','Моя анкета','Районы, опыт и график']]).map(([intent,title,description])=><button key={intent} disabled={!ready} onClick={()=>navigate(intent)}><span className="action-icon"><ArrowRight size={22}/></span><b>{title}</b><small>{description}</small><ArrowUpRight size={16}/></button>)}</div><div className="welcome-trust"><ShieldCheck size={16}/><span>Вы подтверждаете публикации, брони и назначения.</span></div><button className="demo-link" disabled={!ready} onClick={()=>send('Покажи учебный пример')}>Учебный режим · подключит три роли<ArrowRight size={14}/></button></div>:<div className="chat-messages" aria-live="polite" aria-relevant="additions">{messages.map(m=><div key={m.id} className={'chat-message '+m.sender}>{m.sender==='assistant'&&<div className="assistant-mark" aria-hidden="true"><Sparkles size={17}/></div>}<div className="message-content">{m.sender==='assistant'&&<div className="message-author">AI Аренда</div>}<p>{m.text}</p>{m.block&&renderBlock(m)}</div></div>)}{busy&&<div className="chat-message assistant"><div className="assistant-mark"><Sparkles size={17}/></div><div className="thinking"><LoaderCircle size={14}/>Проверяю и сохраняю…</div></div>}</div>}</div><div className="chat-bottom">{flow&&<div className="flow-progress"><span>{flow.kind==='property'?'Добавление квартиры':'Заполнение профиля'} · {flow.index+1} из {flow.questions.length}</span><button onClick={()=>{setFlow(null);say('Ввод остановлен. Можем начать другую задачу.');}}>Остановить ввод</button></div>}<form className="chat-composer" onSubmit={e=>{e.preventDefault();send();}}><textarea ref={composer} value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();send();}}} rows={1} maxLength={2500} disabled={busy} placeholder={flow?'Напишите ваш ответ…':'Спросите об аренде или выберите действие…'} aria-label="Сообщение AI Аренде"/><button className="chat-send" disabled={busy||!ready||!input.trim()} aria-label="Отправить сообщение">{busy?<LoaderCircle size={20}/>:<ArrowUp size={21}/>}</button></form><div className="chat-footnote"><span>Ассистент помогает с действиями. Проверяйте сведения перед подтверждением.</span><span>Enter ↵</span></div></div></main>}</div>
    {panel==='roles'&&<Modal title="Ваши кабинеты" subtitle="Один аккаунт — отдельные задачи и данные каждой роли" onClose={()=>setPanel('dashboard')}><div className="modal-content"><div className="role-cabinets">{(Object.keys(roleInfo) as Role[]).map(r=>{const Icon=roleInfo[r].icon,connected=JSON.parse(profile?.roles||'[]').includes(r);return <button key={r} onClick={()=>connected?switchRole(r):(setPanel(null),beginProfile(r,'profile-done',data,true))}><Icon size={24}/><span><b>{roleInfo[r].name}</b><small>{connected?(role===r?'Текущий кабинет':'Открыть кабинет'):'Подключить роль и заполнить профиль'}</small></span>{role===r?<Check size={18}/>:<ArrowRight size={18}/>}</button>;})}</div>{panelError&&<div className="form-error" role="alert">{panelError}</div>}</div></Modal>}
    {panel==='automation'&&<Modal title="Правила ассистента" subtitle="Операционные правила владельца недвижимости" onClose={()=>setPanel('dashboard')}><AutomationForm settings={data.settings||{}} onSave={async body=>{const result=await post('settings',body);await load();say(result.message);setPanel('dashboard');}}/></Modal>}
    {(panel==='add-property'||panel==='edit-property')&&<PropertyWizard key={panel+(selectedProperty?.id||'')} initial={panel==='edit-property'?selectedProperty:null} profile={profile} ownerId={myId} onSave={publishProperty} onClose={()=>setPanel(null)}/>}
    {panel==='account'&&<Modal title="Ваш аккаунт" subtitle="Профиль, контакты и доступные возможности" onClose={()=>setPanel(null)}><div className="modal-content"><div className="account-summary"><span className="avatar large"><UserRound size={27}/></span><div><h3>{user?displayName:'Вы пока не вошли'}</h3><p>{user?.email||'Войдите, чтобы сохранять квартиры и бронирования.'}</p></div></div>{user?<><dl className="detail-list"><div><dt>Контакт</dt><dd>{profile?.contact||'Не указан'}</dd></div><div><dt>Город</dt><dd>{profile?.city||'Не указан'}</dd></div><div><dt>Возможности</dt><dd>{profile?.roles?JSON.parse(profile.roles).map((r:string)=>({owner:'Владелец',guest:'Клиент',cleaner:'Исполнитель'} as Row)[r]).join(' · '):'Профиль ещё не заполнен'}</dd></div></dl><div className="notice neutral"><UserRound size={18}/><p><b>Один аккаунт для всех задач</b><span>Вы можете сдавать жильё, бронировать квартиры и выполнять уборки.</span></p></div><div className="account-links"><button onClick={()=>openPanel('roles')}><UserRound size={18}/>Переключить или подключить кабинет<ArrowRight size={16}/></button><button onClick={()=>navigate('profile')}><Settings2 size={18}/>Заполнить или изменить профиль<ArrowRight size={16}/></button><button onClick={()=>navigate('cleaner-profile')}><Brush size={18}/>Анкета исполнителя<ArrowRight size={16}/></button><button onClick={signout}><LogOut size={18}/>Выйти из аккаунта</button></div></>:<a className="primary-button" href="/signin-with-chatgpt?return_to=/" target="_top">Войти через ChatGPT<ArrowUpRight size={16}/></a>}</div></Modal>}
    {panel==='properties'&&<Modal title="Мои объекты" subtitle="Объекты вашего аккаунта и действия с ними" wide onClose={()=>setPanel(null)}><div className="modal-content">{!user?<div className="empty-state"><UserRound size={30}/><h3>Войдите, чтобы увидеть квартиры</h3><p>Объекты привязаны к вашему аккаунту.</p><a className="primary-button" href="/signin-with-chatgpt?return_to=/">Войти через ChatGPT</a></div>:<>{data.ownProperties.length?<div className="property-grid">{data.ownProperties.map((item:Row)=><PropertyCard key={item.id} item={item} own onDetails={()=>{setSelectedProperty(item);setPanel('property-detail');}} onAction={()=>{setSelectedProperty(item);setPanel('property-detail');}}/>)}</div>:<div className="empty-state"><Building2 size={34}/><h3>Здесь будут ваши объекты</h3><p>Добавьте расположение, цену и правила.<br/>Перед публикацией вы проверите объявление.</p></div>}<button className="primary-button full-width" onClick={()=>runIntent('property')}><Plus size={17}/>Добавить объект</button></>}</div></Modal>}
    {panel==='property-detail'&&selectedProperty&&<Modal title={selectedProperty.title} subtitle={selectedProperty.city+' · '+selectedProperty.district} wide onClose={()=>setPanel(null)}><div className="modal-content"><div className="detail-cover"><Home size={44} strokeWidth={1.25}/><span>Фотографии ещё не поддерживаются</span></div><div className="detail-price"><strong>{money(selectedProperty.price)}<small> / {selectedProperty.rate_unit==='hour'?'час':'сутки'}</small></strong>{selectedProperty.demo_owner&&<span className="status-badge">Учебный объект</span>}</div><dl className="detail-list"><div><dt>Вместимость</dt><dd>{selectedProperty.rooms} комн. · до {selectedProperty.capacity} гостей</dd></div><div><dt>Между гостями</dt><dd>{selectedProperty.cleaning_minutes} минут на уборку</dd></div><div><dt>Адрес</dt><dd>{selectedProperty.address||'Доступен после подтверждения брони'}</dd></div></dl><h3>Описание и правила</h3><p className="detail-description">{selectedProperty.description}</p>{selectedProperty.owner_id===myId?<div className="inline-actions"><button className="primary-button" onClick={()=>setPanel('edit-property')}>Редактировать</button><button className="secondary-button" onClick={()=>{setPanelError('');setPanel('property-visibility');}}>{selectedProperty.published?'Скрыть из каталога':'Вернуть в каталог'}</button><button className="primary-button" onClick={()=>{setRole('owner');setPanel(null);listBookings({...data,bookings:data.bookings.filter((b:Row)=>b.property_id===selectedProperty.id)},'owner');}}>Заявки по квартире</button><button className="secondary-button" onClick={()=>{setRole('owner');setPanel(null);say('Создайте задание по этой квартире.','job-form',{properties:[selectedProperty]});}}>Создать уборку</button></div>:<button className="primary-button full-width" onClick={()=>{setPanel(null);chooseProperty(selectedProperty);}}>Выбрать даты проживания<CalendarDays size={17}/></button>}</div></Modal>}
    {notificationToast&&<aside className="assistant-toast" role="status"><span className="notification-icon"><Bell size={18}/></span><div><b>Новое событие · AI Аренда</b><p>{notificationToast.body}</p><button onClick={()=>{openNotification(notificationToast);setNotificationToast(null);}}>Посмотреть<ArrowRight size={14}/></button></div><button className="icon-button" aria-label="Закрыть оповещение" onClick={()=>setNotificationToast(null)}><X size={16}/></button></aside>}
    {panel==='property-visibility'&&selectedProperty&&<Modal title={selectedProperty.published?'Скрыть квартиру из каталога?':'Вернуть квартиру в каталог?'} onClose={()=>setPanel('property-detail')} locked={busy}><div className="modal-content"><p className="detail-description">{selectedProperty.published?'Новые гости не увидят это объявление. Текущие бронирования и уборки сохранятся. Квартиру можно будет вернуть в каталог.':'Квартира снова появится в поиске. Проверьте актуальность цены и условий.'}</p>{panelError&&<div className="form-error" role="alert">{panelError}</div>}<button className="primary-button full-width" disabled={busy} onClick={async()=>{setBusy(true);try{await post('properties/'+selectedProperty.id,{action:'visibility',published:!selectedProperty.published});await load().catch(()=>setPollError(true));setPanel('properties');}catch(e:any){setPanelError(e.message);}finally{setBusy(false);}}}>{busy?'Сохраняю…':selectedProperty.published?'Скрыть квартиру':'Вернуть в каталог'}</button></div></Modal>}
    {panel==='notifications'&&<Modal title="Уведомления" subtitle={unread?'Непрочитанных: '+unread:'Вы в курсе последних событий'} onClose={()=>setPanel(null)}><div className="modal-content">{!user?<div className="empty-state"><Bell size={32}/><h3>События появятся после входа</h3><p>Заявки гостей, назначения и результаты уборок будут здесь.</p><a className="primary-button" href="/signin-with-chatgpt?return_to=/">Войти через ChatGPT</a></div>:<>{unread>0&&<button className="text-button" onClick={markRead}>Отметить всё прочитанным<Check size={15}/></button>}{panelError&&<div className="form-error" role="alert">{panelError}</div>}{data.notifications.length?<div className="notification-list">{data.notifications.map((n:Row)=><article key={n.id} className={'notification-item '+(!n.read?'is-unread':'')}><span className="notification-icon"><Bell size={17}/></span><div><b>Событие по аренде</b><p>{n.body}</p><small>{date(n.created_at)}</small><button className="notification-action" onClick={()=>openNotification(n)}>Посмотреть<ArrowRight size={13}/></button></div>{!n.read&&<span className="nav-dot"/>}</article>)}</div>:<div className="empty-state"><Bell size={34}/><h3>Пока новых событий нет</h3><p>Здесь появятся заявки, подтверждения брони и обновления по уборкам.</p></div>}<div className="notice neutral"><Info size={18}/><p><b>Уведомления внутри приложения</b><span>События обновляются каждые 30 секунд, пока вкладка открыта. Отправка в мессенджеры пока не подключена.</span></p></div></>}</div></Modal>}
    {(panel==='guide'||panel==='about')&&<Modal title={panel==='guide'?'Как сдать квартиру':'О сервисе'} subtitle="Понятные действия и подтверждения на каждом важном шаге" onClose={()=>setPanel(null)}><div className="modal-content"><ol className="guide-list"><li><span>1</span><div><h3>Добавьте квартиру</h3><p>Укажите адрес, стоимость и правила. Проверьте объявление перед публикацией.</p></div></li><li><span>2</span><div><h3>Рассмотрите заявку гостя</h3><p>Проверьте даты и подтвердите бронь. Адрес откроется гостю после подтверждения.</p></div></li><li><span>3</span><div><h3>Организуйте уборку</h3><p>Укажите вознаграждение, назначьте исполнителя и примите работу по отчёту.</p></div></li></ol><div className="notice neutral"><Info size={19}/><p><b>Что доступно в пилоте</b><span>Каталог, заявки, уборки и уведомления работают. Ассистент ведёт по сценариям; свободная языковая модель, платежи, фото и мессенджеры пока не подключены. Проверка документов и объектов не выполняется.</span></p></div><button className="primary-button full-width" onClick={()=>runIntent('property')}><Plus size={17}/>Добавить свою квартиру</button></div></Modal>}
    </div>;
}
